export interface StateMapPath {
  name: string;
  d: string;
  cx: number;
  cy: number;
}

export const INDIA_MAP_DIMENSIONS = {
  width: 640,
  height: 720,
  minLng: 68.0,
  maxLng: 97.5,
  minLat: 7.5,
  maxLat: 37.5,
  padding: 20
};

export function projectCoord(lat: number, lng: number): [number, number] {
  const { width, height, minLng, maxLng, minLat, maxLat, padding } = INDIA_MAP_DIMENSIONS;
  const x = padding + ((lng - minLng) / (maxLng - minLng)) * (width - 2 * padding);
  const y = height - padding - ((lat - minLat) / (maxLat - minLat)) * (height - 2 * padding);
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}

